// pages/UserProfile.tsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { apiService } from '../services/api';
import './UserProfile.css';

const UserProfile: React.FC = () => {
  const { user, updateUser } = useAuth();
  const [minioInfo, setMinioInfo] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [userFiles, setUserFiles] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'account' | 'files'>('account');

  useEffect(() => {
    const loadUserData = async () => {
      if (user) {
        try {
          const [info, files] = await Promise.all([
            apiService.getUserMinioInfo(),
            apiService.getUserFiles()
          ]);
          setMinioInfo(info);
          setUserFiles(files);
        } catch (error) {
          console.error('Error loading user data:', error);
        } finally {
          setLoading(false);
        }
      }
    };

    loadUserData();
  }, [user]);

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString('ru-RU', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const handleDownload = async (url: string, filename: string) => {
    try {
      await apiService.downloadFile(url, filename);
    } catch (error) {
      console.error('Error downloading file:', error);
      alert('Ошибка при скачивании файла');
    }
  };

  if (!user) {
    return (
      <div className="profile-container">
        <div className="profile-card">
          <h2>⚠️ Доступ запрещен</h2>
          <p>Для просмотра профиля необходимо <a href="/login">войти в систему</a></p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="profile-container">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Загрузка профиля...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="user-profile">
      <div className="profile-header">
        <h1>Профиль пользователя</h1>
        
      </div>

      <div className="profile-tabs">
        <button 
          className={`tab-button ${activeTab === 'account' ? 'active' : ''}`}
          onClick={() => setActiveTab('account')}
        >
          📋 Информация аккаунта
        </button>
        <button 
          className={`tab-button ${activeTab === 'files' ? 'active' : ''}`}
          onClick={() => setActiveTab('files')}
        >
          📁 История файлов ({userFiles.length})
        </button>
      </div>

      {activeTab === 'account' ? (
        <div className="profile-grid">
          <div className="profile-card">
            <h2>📋 Информация аккаунта</h2>
            <div className="info-grid">
              <div className="info-item">
                <span className="info-label">Имя пользователя:</span>
                <span className="info-value">{user.username}</span>
              </div>
              
              {user.email && (
                <div className="info-item">
                  <span className="info-label">Email:</span>
                  <span className="info-value">{user.email}</span>
                </div>
              )}
              
              {user.created_at && (
                <div className="info-item">
                  <span className="info-label">Дата регистрации:</span>
                  <span className="info-value">{formatDate(user.created_at)}</span>
                </div>
              )}
              
              
              {minioInfo && (
                <>
                  <div className="info-item">
                    <span className="info-label">Хранилище:</span>
                    <span className="info-value storage-badge">MinIO</span>
                  </div>
                  
                  {minioInfo.folder && (
                    <div className="info-item">
                      <span className="info-label">Папка в MinIO:</span>
                      <span className="info-value code">{minioInfo.folder}</span>
                    </div>
                  )}
                  
                  {minioInfo.total_files !== undefined && (
                    <div className="info-item">
                      <span className="info-label">Всего файлов:</span>
                      <span className="info-value">{minioInfo.total_files}</span>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>

          <div className="profile-card">
            <h2>⚙️ Системная информация</h2>
            <div className="info-grid">
            
              
              <div className="info-item">
                <span className="info-label">Методы цензурирования:</span>
                <span className="info-value">Пикселизация</span>
              </div>
              
              <div className="info-item">
                <span className="info-label">Поддерживаемые форматы:</span>
                <span className="info-value">JPG, PNG</span>
              </div>
              
              <div className="info-item">
                <span className="info-label">Максимальный размер файла:</span>
                <span className="info-value">10 MB</span>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="files-section">
          <div className="files-header">
            <h2>📁 История файлов</h2>
            <div className="files-stats">
              <span className="stat-item">Всего: {userFiles.length}</span>
              <span className="stat-item">
                Общий размер: {formatFileSize(userFiles.reduce((acc, file) => acc + (file.size || 0), 0))}
              </span>
            </div>
          </div>

          {userFiles.length === 0 ? (
            <div className="empty-files">
              <div className="empty-icon">📭</div>
              <h3>Файлы не найдены</h3>
              <p>У вас пока нет загруженных файлов</p>
              <a href="/redaction" className="upload-link">
                🖼️ Перейти в редактор
              </a>
            </div>
          ) : (
            <div className="files-grid">
              {userFiles.map((file, index) => (
                <div key={index} className="file-card">
                  <div className="file-preview">
                    {file.name?.match(/\.(jpg|jpeg|png|gif|bmp|webp)$/i) ? (
                      <img 
                        src={file.url} 
                        alt={file.name} 
                        className="file-image"
                        onError={(e) => {
                          (e.target as HTMLImageElement).src = '/placeholder-image.png';
                        }}
                      />
                    ) : (
                      <div className="file-icon">
                        {file.name?.match(/\.(pdf)$/i) ? '📄' : 
                         file.name?.match(/\.(doc|docx)$/i) ? '📝' : 
                         file.name?.match(/\.(xls|xlsx)$/i) ? '📊' : 
                         '📁'}
                      </div>
                    )}
                  </div>
                  
                  <div className="file-info">
                    <div className="file-name" title={file.name || file.object_name}>
                      {file.name || file.object_name || 'Без названия'}
                    </div>
                    
                    <div className="file-details">
                      {file.size && (
                        <span className="file-size">📦 {formatFileSize(file.size)}</span>
                      )}
                      
                      {file.last_modified && (
                        <span className="file-date">📅 {formatDate(file.last_modified)}</span>
                      )}
                      
                      {file.type && (
                        <span className="file-type">🎯 {file.type}</span>
                      )}
                    </div>
                    
                    {file.object_name && (
                      <div className="file-id" title="Object name в MinIO">
                        🏷️ {file.object_name.substring(0, 30)}...
                      </div>
                    )}
                  </div>
                  
                  <div className="file-actions">
                    {file.url && (
                      <a 
                        href={file.url} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="action-button view"
                        title="Просмотреть"
                      >
                        👁️
                      </a>
                    )}
                    
                    <button 
                      onClick={() => handleDownload(file.url, file.name || file.object_name)}
                      className="action-button download"
                      title="Скачать"
                    >
                      ⬇️
                    </button>
                    
                    {file.url && (
                      <button 
                        onClick={() => navigator.clipboard.writeText(file.url)}
                        className="action-button copy"
                        title="Копировать ссылку"
                      >
                        📋
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {minioInfo && (
            <div className="storage-info">
              <h3>💾 Информация о хранилище</h3>
              <div className="storage-details">
                <div className="storage-item">
                  <span className="storage-label">Провайдер:</span>
                  <span className="storage-value">{minioInfo.provider || 'MinIO'}</span>
                </div>
                
                {minioInfo.bucket && (
                  <div className="storage-item">
                    <span className="storage-label">Бакет:</span>
                    <span className="storage-value">{minioInfo.bucket}</span>
                  </div>
                )}
                
                {minioInfo.folder && (
                  <div className="storage-item">
                    <span className="storage-label">Папка пользователя:</span>
                    <span className="storage-value code">{minioInfo.folder}</span>
                  </div>
                )}
                
                <div className="storage-item">
                  <span className="storage-label">Всего файлов:</span>
                  <span className="storage-value">{userFiles.length}</span>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default UserProfile;
